public class InnerProgramAdBreakFactory(Action<Humidifier.MediaTailor.ProgramTypes.AdBreak> factoryAction = null) : SubResourceFactory<Humidifier.MediaTailor.ProgramTypes.AdBreak>
{

    internal InnerProgramTimeSignalMessageFactory TimeSignalMessageFactory { get; set; }

    internal InnerProgramSpliceInsertMessageFactory SpliceInsertMessageFactory { get; set; }

    internal InnerProgramSlateSourceFactory SlateFactory { get; set; }

    protected override Humidifier.MediaTailor.ProgramTypes.AdBreak Create()
    {
        var adBreakResult = CreateAdBreak();
        factoryAction?.Invoke(adBreakResult);

        return adBreakResult;
    }

    private Humidifier.MediaTailor.ProgramTypes.AdBreak CreateAdBreak()
    {
        var adBreakResult = new Humidifier.MediaTailor.ProgramTypes.AdBreak();

        return adBreakResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.ProgramTypes.AdBreak result)
    {
        base.CreateChildren(result);

        result.TimeSignalMessage ??= TimeSignalMessageFactory?.Build();
        result.SpliceInsertMessage ??= SpliceInsertMessageFactory?.Build();
        result.Slate ??= SlateFactory?.Build();
    }

} // End Of Class

